def comps(g, bg):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; res=[]
    import sys
    sys.setrecursionlimit(10000)
    def dfs(r,c,cells):
        st=[(r,c)]; seen[r][c]=True
        while st:
            x,y=st.pop(); cells.append((x,y))
            for dx in(-1,0,1):
                for dy in(-1,0,1):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and g[nx][ny]!=bg:
                        seen[nx][ny]=True; st.append((nx,ny))
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and not seen[r][c]:
                cells=[]; dfs(r,c,cells)
                cols=set(g[x][y] for x,y in cells)
                res.append((tuple(sorted(cells)), frozenset(cols)))
    return res
def norm(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return tuple(sorted((r-mr,c-mc) for r,c in cells))
